begin;
update public.lw_briefs set payload=payload || '{"guide":{"id":"omega3","intro":"생선과 보충제에 들어 있는 오메가3. 원료 총량과 EPA·DHA 함량을 구분해 살펴봅니다.","title":"오메가3, EPA와 DHA 표시부터 읽어보세요","source":{"url":"https://ods.od.nih.gov/factsheets/Omega3FattyAcids-Consumer/","name":"미국 NIH ODS · Omega-3 Fatty Acids"},"category":"오메가3","sections":[{"text":"ALA·EPA·DHA는 오메가3 지방산의 종류입니다. 세포막의 구성 성분이며 생선·견과류·식물성 기름 등에서 섭취할 수 있습니다.","title":"성분과 기능"},{"text":"EPA·DHA는 중성지방 수치 감소와 관련이 있지만, 보충제의 효과는 목적과 개인 상태에 따라 다릅니다. 질병 치료를 위해 임의로 고용량을 섭취하지 마세요.","title":"효과·효능"},{"text":"제품 라벨의 1일 섭취량을 따르세요. 어유 총량과 EPA·DHA의 합산 함량을 구분하고, 다른 보충제와 중복되는지 확인하세요.","title":"섭취 방법"},{"text":"생선·해산물, 견과류·씨앗류 등 식품에서도 오메가3를 섭취할 수 있습니다. 보충제 필요 여부는 평소 식사와 함께 판단하세요.","title":"식사와 함께 살펴보기"},{"text":"고용량은 항응고제와 상호작용할 수 있습니다. 약을 복용하거나 질환이 있다면 의료진과 먼저 상담하세요.","title":"섭취 전 확인"},{"title":"근거의 대상과 한계","text":"NIH ODS 자료는 음식 속 오메가3와 보충제를 구분합니다. 생선을 먹는 식생활의 관찰 결과를 특정 캡슐의 효과로 그대로 옮길 수는 없습니다. EPA·DHA의 중성지방 관련 설명을 모든 사람의 심혈관질환 예방 효과로 확대하지 마세요. 제품 비교는 치료 선택을 대신하지 않습니다."},{"title":"라벨 비교 예시 · 가상 제품","text":"A의 1일 분량은 어유 1,000mg 중 EPA 180mg·DHA 120mg, B는 어유 800mg 중 EPA 240mg·DHA 160mg이라고 가정하면 합산량은 A 300mg, B 400mg입니다. 원료 총량 순서와 EPA·DHA 합산량 순서가 다릅니다. 같은 하루 분량을 기준으로 계산한 예시이며 어느 제품의 복용을 권하는 수치는 아닙니다."},{"title":"상담 전에 준비할 정보","text":"어유·조류유 등 원료, EPA·DHA 각각의 1일 함량, 다른 영양제와 약의 목록을 적습니다. 항응고제 사용 등은 의료진에게 알리세요. 알레르기와 제품별 주의사항도 확인합니다. 이 사이트의 별점·관심도는 섭취 적합성 판단 근거가 아닙니다."}],"reviewNote":"아래 평점은 해당 쇼핑몰 이용자의 구매 평가이며, 제품 효능을 검증한 임상 지표가 아닙니다.","sourceCheckedAt":"2026-10-18","modifiedAt":"2026-10-18","author":"루나야 · AI 작성 보조","reviewStatus":"공식 자료 대조 완료 · 운영자 최종 검토 대기 · 의료인 검토 미실시"},"contentReview":{"created":"2026-10-18","modified":"2026-10-18","sourcesChecked":"2026-10-18","author":"루나야 · AI 작성 보조","review":"공식 자료 대조 완료 · 운영자 최종 검토 대기 · 의료인 검토 미실시"},"reviewedNews":{"title":"AI 분석과 약사 확인을 함께 다룬 영양제 관리 서비스 보도","source":"매일경제 · 방영덕 기자","url":"https://www.mk.co.kr/news/it/12159862","published":"2026-09-22","checked":"2026-10-18","summary":"매일경제는 로그싱크가 의약품·영양제 정보를 분석하고 약사가 결과를 검토하는 PNr.365 서비스를 상용화한다고 보도했습니다. 서비스 출시 및 회사 설명을 전하는 기사이며, 서비스 효과를 입증한 임상시험 결과와는 구분해야 합니다.","analysis":"루나야가 이 보도에서 주목한 부분은 제품 추천보다 먼저 성분 중복과 복용약을 확인하는 순서입니다. 여러 병을 한 목록으로 정리하는 일은 상담 준비에 도움이 되지만, 목록을 만들었다는 사실만으로 병용 안전성이 검증되지는 않습니다. 루나야의 가격 비교·HTML 목록 기능에도 자동 약물 상호작용 판정 기능은 없습니다.","questions":["현재 먹는 제품과 처방약을 빠뜨리지 않고 기록했는지 확인하세요.","성분명·하루 함량·섭취 횟수가 적힌 라벨을 상담 때 함께 제시하세요.","새로운 서비스를 소개한 보도와 독립적인 효과 검증 자료를 구분하세요."],"limit":"원문 확인일 기준의 배경기사 해설입니다. 오늘 발생한 뉴스로 재분류하지 않으며, 자동 수집된 다른 기사까지 원문 확인을 마쳤다는 뜻이 아닙니다."}}'::jsonb, updated_at=now() where day='2026-10-18';
update public.lw_briefs set payload=payload || '{"guide":{"id":"vitamin-c","intro":"항산화와 콜라겐 형성에 관여하는 비타민C. 과일·채소의 섭취와 보충제 라벨을 함께 살펴보세요.","title":"비타민C, 많이 먹기 전에 알아둘 기본","source":{"name":"미국 NIH ODS · Vitamin C (전문가용 자료)","url":"https://ods.od.nih.gov/factsheets/VitaminC-HealthProfessional/"},"category":"비타민C","sections":[{"text":"비타민C는 수용성 영양소로 항산화 작용을 하며, 콜라겐 형성과 식물성 식품의 철 흡수에 관여합니다.","title":"성분과 기능"},{"text":"정상적인 영양 상태를 유지하는 기능과 특정 질병의 치료 효과는 구분해야 합니다. 고용량 보충제를 질병의 예방·치료 목적으로 임의 사용하지 마세요.","title":"효과·효능"},{"text":"보충제의 제품별 1일 섭취량을 따르세요. 과일과 채소에서도 비타민C를 섭취하므로 식사와 다른 영양제의 함량을 함께 확인하세요.","title":"섭취 방법"},{"text":"많이 섭취하면 설사·메스꺼움·복부 경련이 생길 수 있습니다. 미국 NIH의 성인 상한 섭취량은 음식과 보충제를 합쳐 하루 2,000mg이며, 권장 섭취량을 뜻하지 않습니다.","title":"고함량 섭취 주의"},{"text":"철 과잉 축적 질환이 있거나 항암 치료 중이라면 보충제 사용 전 의료진에게 확인하세요.","title":"섭취 전 확인"},{"title":"근거의 대상과 한계","text":"NIH ODS의 영양소 기능 설명과 질병 예방·치료 효과는 별개입니다. 결핍을 예방하는 영양 보충의 목적을 고함량 제품의 우월성으로 해석하지 않습니다. 미국 기준의 섭취 참고값을 국내 제품의 지침이나 개인 처방으로 사용하지 마세요."},{"title":"중복 함량을 합산하는 예 · 가상 제품","text":"종합비타민에 1일 기준 비타민C 100mg, 단일 제품에 500mg이 표시되어 있다면 보충제에서 확인한 합계는 600mg입니다. 이 값은 음식 섭취량을 포함하지 않으며 권장량·안전량 판정도 아닙니다. 함량 기준이 1정인지 하루 분량인지 먼저 맞춥니다."},{"title":"확인하고 남겨둘 질문","text":"왜 보충하려는지, 과일·채소 섭취와 어떤 관계인지, 함께 먹는 제품의 동일 성분은 얼마인지 기록하세요. 고용량 사용이나 치료 중인 상황은 의료진에게 확인합니다. 상한량이라는 말은 그만큼 먹으면 이롭다는 목표량을 뜻하지 않습니다."}],"reviewNote":"아래 평점은 해당 쇼핑몰 이용자의 구매 평가이며, 제품 효능을 검증한 임상 지표가 아닙니다.","sourceCheckedAt":"2026-10-18","modifiedAt":"2026-10-18","author":"루나야 · AI 작성 보조","reviewStatus":"공식 자료 대조 완료 · 운영자 최종 검토 대기 · 의료인 검토 미실시"},"contentReview":{"created":"2026-10-18","modified":"2026-10-18","sourcesChecked":"2026-10-18","author":"루나야 · AI 작성 보조","review":"공식 자료 대조 완료 · 운영자 최종 검토 대기 · 의료인 검토 미실시"},"reviewedNews":{"title":"AI 분석과 약사 확인을 함께 다룬 영양제 관리 서비스 보도","source":"매일경제 · 방영덕 기자","url":"https://www.mk.co.kr/news/it/12159862","published":"2026-09-22","checked":"2026-10-18","summary":"매일경제는 로그싱크가 의약품·영양제 정보를 분석하고 약사가 결과를 검토하는 PNr.365 서비스를 상용화한다고 보도했습니다. 서비스 출시 및 회사 설명을 전하는 기사이며, 서비스 효과를 입증한 임상시험 결과와는 구분해야 합니다.","analysis":"루나야가 이 보도에서 주목한 부분은 제품 추천보다 먼저 성분 중복과 복용약을 확인하는 순서입니다. 여러 병을 한 목록으로 정리하는 일은 상담 준비에 도움이 되지만, 목록을 만들었다는 사실만으로 병용 안전성이 검증되지는 않습니다. 루나야의 가격 비교·HTML 목록 기능에도 자동 약물 상호작용 판정 기능은 없습니다.","questions":["현재 먹는 제품과 처방약을 빠뜨리지 않고 기록했는지 확인하세요.","성분명·하루 함량·섭취 횟수가 적힌 라벨을 상담 때 함께 제시하세요.","새로운 서비스를 소개한 보도와 독립적인 효과 검증 자료를 구분하세요."],"limit":"원문 확인일 기준의 배경기사 해설입니다. 오늘 발생한 뉴스로 재분류하지 않으며, 자동 수집된 다른 기사까지 원문 확인을 마쳤다는 뜻이 아닙니다."}}'::jsonb, updated_at=now() where day='2026-10-17';
commit;
select day, jsonb_array_length(payload->'guide'->'sections') as guide_sections, payload->'contentReview'->>'modified' as modified from public.lw_briefs order by day desc;